#include "list.h"
#include "test.h"
int main(void){rtos_list_t a,b;rtos_list_node_t n1,n2;rtos_list_init(&a);rtos_list_init(&b);rtos_list_node_init(&n1);rtos_list_node_init(&n2);TEST_ASSERT(rtos_list_push_back(&a,&n1));TEST_ASSERT(!rtos_list_push_back(&b,&n1));TEST_ASSERT(!rtos_list_remove(&b,&n1));TEST_ASSERT(rtos_list_push_back(&a,&n2));TEST_ASSERT(rtos_list_validate(&a));n2.previous=0;TEST_ASSERT(!rtos_list_validate(&a));n2.previous=&n1;TEST_ASSERT(rtos_list_validate(&a));TEST_PASS("ownership and invariants");return 0;}